import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        print(0)
        return

    n = int(input_data[0])
    m = int(input_data[1])

    grid = []
    idx = 2
    for _ in range(n):
        row_str = input_data[idx]
        idx += 1
        grid.append(list(row_str))

    visited = [[False for _ in range(m)] for _ in range(n)]
    count = 0

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            curr_r, curr_c = stack.pop()
            if 0 <= curr_r < n and 0 <= curr_c < m:
                if not visited[curr_r][curr_c] and grid[curr_r][curr_c] == 'X':
                    visited[curr_r][curr_c] = True
                    stack.append((curr_r + 1, curr_c))
                    stack.append((curr_r - 1, curr_c))
                    stack.append((curr_r, curr_c + 1))
                    stack.append((curr_r, curr_c - 1))

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X' and not visited[i][j]:
                count += 1
                dfs(i, j)

    print(count)

if __name__ == "__main__":
    solve()
